/**
 * Types and loader for the Score Lab golden file, test/oracle/__fixtures__/SAMPLE_golden.v0.3.json.
 *
 * Every number in it is invented SAMPLE data generated by the Score Lab v0.3 (common rule 4).
 * Test code only: never import this, or the fixture, from src/.
 *
 * Acceptance check for CSN-031 to CSN-038: feed `inputs` through the engine and match `outputs`
 * within `meta.tolerance.points` (labels exactly). Price and volume series are stored as base64
 * little-endian float64 so they round-trip bit for bit; use {@link coinSeries} to decode them.
 */
import { readFileSync } from 'node:fs';

export const GOLDEN_PATH = new URL('./__fixtures__/SAMPLE_golden.v0.3.json', import.meta.url);

export type Num = number;
export type Horizon = 'short' | 'medium' | 'long';
export type Profile = 'safe' | 'moderate' | 'risky';

export interface GoldenMeta {
  readonly description: string;
  readonly format: number;
  readonly labFile: string;
  readonly labSha256: string;
  readonly labBytes: number;
  readonly labVersion: string;
  readonly extractedOn: string;
  readonly extractor: string;
  readonly node: string;
  readonly days: number;
  readonly scoredDay: number;
  readonly prevDay: number;
  readonly horizons: readonly Horizon[];
  readonly profiles: readonly Profile[];
  readonly tolerance: { readonly points: number; readonly labels: 'exact' };
  readonly series: {
    readonly encoding: 'base64-float64le';
    readonly priceDays: number;
    readonly volumeDays: number;
    readonly note: string;
  };
}

export interface GoldenCoinInput {
  readonly s: string;
  readonly n: string;
  readonly sec: string;
  readonly tier: string;
  readonly chain: string;
  readonly nar: readonly string[];
  readonly price: Num;
  readonly mcap: Num;
  readonly rank: number;
  readonly [field: string]: unknown;
  readonly series: { readonly p: string; readonly v: string };
}

export interface GoldenRow {
  readonly s: string;
  readonly raw: Readonly<Record<string, unknown>>;
  readonly pct: Readonly<Record<string, Num | null>>;
  readonly pillar: Readonly<Record<string, Num | null>>;
  readonly hype: boolean;
  readonly temp: {
    readonly v: Num;
    readonly band: string;
    readonly parts: Record<string, Num | null>;
  };
  readonly coverage: Num;
  readonly quality: Num;
  readonly timingBase: Num;
  readonly tempAdj: Num;
  readonly timing: Num;
  readonly quadrant: string;
  readonly archetype: string;
  readonly upside: Readonly<Record<string, unknown>>;
}

export interface GoldenScore {
  readonly s: string;
  readonly score: Num;
  readonly base: Num;
  readonly q: Num;
  readonly cap: Num | null;
  readonly label: string;
  readonly quality: Num;
  readonly timing: Num;
  readonly quadrant: string;
  readonly archetype: string;
  readonly qWeights: Readonly<Record<string, Num>>;
  readonly tWeights: Readonly<Record<string, Num>>;
  readonly flags: readonly string[];
  readonly eligible: boolean;
  readonly why: readonly string[];
}

export interface GoldenPrevRow {
  readonly s: string;
  readonly quality: Num;
  readonly timing: Num;
  readonly quadrant: string;
  readonly archetype: string;
  readonly tempBand: string;
  readonly pillar: Readonly<Record<string, Num | null>>;
}

export interface GoldenSignal {
  readonly s: string | null;
  readonly id: string;
  readonly pri?: number;
  readonly extra?: string;
}

export interface GoldenHorizon {
  readonly rows: readonly GoldenRow[];
  readonly scores: Readonly<Record<Profile, readonly GoldenScore[]>>;
  readonly prev: {
    readonly market: { readonly score: Num; readonly label: string };
    readonly cycle: { readonly score: Num; readonly phase: string };
    readonly rows: readonly GoldenPrevRow[];
  };
  readonly signals: readonly GoldenSignal[];
}

export interface GoldenGroup {
  readonly id: string;
  readonly name: string;
  readonly members: readonly string[];
  readonly heat: Num;
  readonly heatPrev: Num;
  readonly delta: Num;
  readonly parts: Readonly<Record<string, Num | null>>;
  readonly raw: Readonly<Record<string, Num | null>>;
  readonly phase: string;
  readonly phaseWeekAgo: string;
}

export interface GoldenMarket {
  readonly weather: {
    readonly score: Num;
    readonly label: string;
    readonly sub: Readonly<Record<string, Num>>;
    readonly eff: Readonly<Record<string, Num>>;
    readonly k: Num;
    readonly raw: Readonly<Record<string, Num>>;
  };
  readonly cycle: Readonly<Record<string, unknown>> & {
    readonly score: Num;
    readonly phase: string;
  };
  readonly sectors: readonly GoldenGroup[];
  readonly narratives: readonly GoldenGroup[];
  readonly outlook: Readonly<Record<string, unknown>> & {
    readonly regime: string;
    readonly fuelLabel: string;
    readonly fragLabel: string;
  };
  readonly archetypeRates: Readonly<Record<string, Readonly<Record<string, Num>>>>;
}

export interface Golden {
  readonly meta: GoldenMeta;
  readonly labConfig: Readonly<Record<string, unknown>>;
  readonly catalogue: Readonly<Record<string, unknown>> & {
    readonly metrics: readonly { id: string; p: string; better: string; peer?: string }[];
    readonly retired: readonly string[];
  };
  readonly inputs: {
    readonly macro: Readonly<Record<string, unknown>>;
    readonly coins: readonly GoldenCoinInput[];
  };
  readonly outputs: {
    readonly market: GoldenMarket;
    readonly horizons: Readonly<Record<Horizon, GoldenHorizon>>;
  };
}

let cached: Golden | undefined;

/** Parse the committed golden (cached per process). */
export function loadGolden(): Golden {
  cached ??= JSON.parse(readFileSync(GOLDEN_PATH, 'utf8')) as Golden;
  return cached;
}

/** Decode a base64 little-endian float64 series. */
export function decodeSeries(b64: string): number[] {
  const buf = Buffer.from(b64, 'base64');
  if (buf.length % 8 !== 0) throw new RangeError('series length is not a multiple of 8 bytes');
  const out: number[] = new Array<number>(buf.length / 8);
  for (let k = 0; k < out.length; k++) out[k] = buf.readDoubleLE(k * 8);
  return out;
}

/**
 * A coin's price and volume series, re-based to absolute day indices: `p[d]` and `v[d]` for
 * d in 0..days-1. Days before the stored volume window are `undefined`.
 */
export function coinSeries(golden: Golden, symbol: string): { p: number[]; v: number[] } {
  const coin = golden.inputs.coins.find((c) => c.s === symbol);
  if (!coin) throw new RangeError(`no coin ${symbol} in the golden`);
  const { days, series } = golden.meta;
  const p = decodeSeries(coin.series.p);
  const vTail = decodeSeries(coin.series.v);
  const v = new Array<number>(days);
  for (let k = 0; k < vTail.length; k++) v[days - series.volumeDays + k] = vTail[k]!;
  return { p, v };
}
